int main() {
    int t;
    cin >> t;
    while (t--) {
        int n, e;
        cin >> n >> e;
        vector<vector<int>> edges(e, vector<int>(2));
        for (auto &ed : edges) cin >> ed[0] >> ed[1];
        int src, dst;
        cin >> src >> dst;
        Solution *s = new Solution();   // big member arrays: keep it on the heap
        cout << "validPath = " << (s->validPath(n, edges, src, dst) ? "true" : "false") << endl;
        delete s;
    }
}

